sql.if:
AND a.tenant_id = #{cu.tenantId}
AND EXISTS (SELECT 1 FROM t_tvac_user_grant g
            WHERE g.user_id = #{cu.userId}
              AND g.object_type = 'ARTICLE'
              AND g.article_id = a.id)

AND EXISTS (SELECT 1 FROM t_tvac_plan p
            WHERE p.article_id = a.id
            )

AND EXISTS (SELECT 1 FROM t_tvac_curve_point c
            WHERE c.article_id = a.id

                AND c.cycle_no = #{q.curveCycleNo}


                AND c.temperature_c >= #{q.tempFromC}


                AND c.temperature_c <= #{q.tempToC}


                AND c.pressure_pa >= #{q.pressureFromPa}


                AND c.pressure_pa <= #{q.pressureToPa}


                AND EXISTS (SELECT 1 FROM t_tvac_plan p2
                            WHERE p2.id = c.plan_id
                            AND p2.id = #{q.planId}

                                AND p2.plan_code = #{q.planCode}


                                AND p2.plan_name LIKE CONCAT('%', #{q.planName}, '%')


                                AND p2.status = #{q.planStatus}


                                AND p2.plan_start_time >= #{q.planTimeFrom}


                                AND p2.plan_start_time <= #{q.planTimeTo}
                            )
            )

mapper.select:
SELECT 'ARTICLE' AS object_type, a.id, a.article_code AS code, a.article_name AS name, a.status, a.tenant_id, a.create_time, a.id AS article_id, a.article_code, a.article_name, a.target_model, a.batch_no, a.status AS article_status, CAST(NULL AS BIGINT) AS plan_id, CAST(NULL AS VARCHAR) AS plan_code, CAST(NULL AS VARCHAR) AS plan_name, CAST(NULL AS VARCHAR) AS plan_status, CAST(NULL AS TIMESTAMP) AS plan_start_time, CAST(NULL AS TIMESTAMP) AS plan_end_time, CAST(NULL AS INT) AS target_cycles, (SELECT COUNT(*) FROM t_tvac_plan p WHERE p.article_id = a.id) AS plan_count, (SELECT COUNT(*) FROM t_tvac_curve_point c WHERE c.article_id = a.id) AS curve_point_count, (SELECT COUNT(*) FROM t_tvac_tm_frame f WHERE f.article_id = a.id) AS frame_count, (SELECT COUNT(*) FROM t_tvac_tm_frame f WHERE f.article_id = a.id AND f.limit_flag <> 'NORMAL') AS abnormal_frame_count FROM t_tvac_article a
AND (a.create_time < #{q.cursorTime} OR (a.create_time = #{q.cursorTime} AND a.id < #{q.cursorId}))
ORDER BY a.create_time DESC, a.id DESC LIMIT #{limit} OFFSET #{offset}

sql.if:
AND EXISTS (SELECT 1 FROM t_tvac_curve_point c
            WHERE c.plan_id = p.id

                AND c.cycle_no = #{q.curveCycleNo}


                AND c.temperature_c >= #{q.tempFromC}


                AND c.temperature_c <= #{q.tempToC}


                AND c.pressure_pa >= #{q.pressureFromPa}


                AND c.pressure_pa <= #{q.pressureToPa}
            )

mapper.select:
SELECT 'PLAN' AS object_type, p.id, p.plan_code AS code, p.plan_name AS name, p.status, a.tenant_id, p.create_time, a.id AS article_id, a.article_code, a.article_name, a.target_model, a.batch_no, a.status AS article_status, p.id AS plan_id, p.plan_code, p.plan_name, p.status AS plan_status, p.plan_start_time, p.plan_end_time, p.target_cycles, CAST(NULL AS BIGINT) AS plan_count, (SELECT COUNT(*) FROM t_tvac_curve_point c WHERE c.plan_id = p.id) AS curve_point_count, (SELECT COUNT(*) FROM t_tvac_tm_frame f WHERE f.plan_id = p.id) AS frame_count, (SELECT COUNT(*) FROM t_tvac_tm_frame f WHERE f.plan_id = p.id AND f.limit_flag <> 'NORMAL') AS abnormal_frame_count FROM t_tvac_plan p JOIN t_tvac_article a ON a.id = p.article_id
AND (p.create_time < #{q.cursorTime} OR (p.create_time = #{q.cursorTime} AND p.id < #{q.cursorId}))
ORDER BY p.create_time DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}
